-- Gerenciador de Anúncios: histórico de tudo que a Gerência alterou na Meta pelo sistema (quem, o quê, antes e depois).
CREATE TABLE IF NOT EXISTS ads_acoes(id INT AUTO_INCREMENT PRIMARY KEY,quando VARCHAR(40) NOT NULL,quem VARCHAR(80) NOT NULL DEFAULT '',nivel VARCHAR(12) NOT NULL DEFAULT '',objeto_id VARCHAR(64) NOT NULL DEFAULT '',nome VARCHAR(250) NOT NULL DEFAULT '',acao VARCHAR(40) NOT NULL DEFAULT '',antes VARCHAR(900) NOT NULL DEFAULT '',depois VARCHAR(900) NOT NULL DEFAULT '',resultado VARCHAR(10) NOT NULL DEFAULT 'OK',erro VARCHAR(500) NOT NULL DEFAULT '',KEY idx_adsa_quando (quando)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
